  private def slv(c: CFormula, toBounds: Boolean)(implicit ta: TypeAnalyzer): Option[(Type => Type, Op => Op, IntExpr => IntExpr)] = c match {
    // False cannot be solved
    case False => None
    // True has the trivial solution
    case True => Some((if (toBounds) TU.topIvars else tEmptySub, oEmptySub, nEmptySub))
    // We solve an Or by solving one of its branches
    case Or(cs) => 
      for (e <- cs) {
        val se = slv(e, toBounds)
        if(se.isDefined)
          return se
      }
      None
    /* To solve an And:
     * 1) Factor the constraint formula into the conjunction of an equality constraint E
     * and additional constraints I
     * 2) Find the principal unifier U of E
     * 3) Apply U to I to get I'
     * TODO: We can solve more constraints if we iterate 1), 2) 3) until we hit a fixed point but we must be careful to ensure termination
     * 4) Solve I' to get a substitution S
     * 5) Return S composed with U
     */
    case _:And => 
      val (newCon, tUnifier, oUnifier, nUnifier) = unify(c).getOrElse(return None)
      newCon match {
        case True => Some((if (toBounds) TU.topIvars compose tUnifier else tUnifier, oUnifier, nUnifier))
        case False => None
        case nc0@And(ts, os, ns) =>
//	  println("nc: " + nc0)
          // Operators only have equality constraints so they should always be solved by unification
          assert(os.isEmpty)
          // So do sizes: an equality left over has no solution, and a size
          // with only disequalities left is left unsolved
          if (ns.exists{case (_, NPrimitive(pe, _)) => !pe.isEmpty}) return None
          val nc = And(ts, os)
          def boundOnly(p: TPrimitive) =
            toBounds && p.pl.forall(l => TU.hasInferenceVars(l) || l.isInstanceOf[BottomType])
          val lowered = ts.filterNot(e => boundOnly(e._2)).map{
              case (k, p@TPrimitive(pl,nl,pu,nu,pe,ne)) => {
                var uni = ta.join(pl.filterNot(TU.hasInferenceVars))
                // Heuristic extension to Dan Smith's algorithm:
                // If there is a single lower bound and it is a trait type, 
                // try all of its ancestors, searching for one that satisfies
                // all upper bounds.
//		println("uni: " + uni)
//		println("pl: " + pl)
                if (pl.size == 1) {
                  pl.head match {
                    case tt:TraitType =>
                      for (a <- (ta.ancestors(tt) ++ List(uni)).toList.sortWith((a,b) => isTrue(ta.subtype(b,a)))) {
		        val proposedMap = cMap(nc, TU.killIvars compose tSubstitution(Map((k,p)).map(_=>(k,a))))
//			println("For ancestor " + a + " proposed map is " + proposedMap)
                        if (isTrue(proposedMap)) {
                          uni = a 
                        }
                      }
                    case _ => 0
                  }
                }
//                println("slv: new (k->uni) = " + k + "->" + uni)
                (k, uni)
              }
            }.toMap
          // A variable that no lower bound fixes takes the meet of its upper bounds, each
          // at the solutions of the other variables it mentions once those are found, as a
          // bound that mentions another static parameter is taken at that parameter's
          // instance; a bound that still mentions a variable, the variable itself among
          // them, is left out.
          var solved: Map[_InferenceVarType, Type] = lowered
          var pending = ts.toList.filter(e => boundOnly(e._2))
          def waits(k: _InferenceVarType, p: TPrimitive) =
            p.pu.exists(u => TU.getInferenceVars(tSubstitution(solved)(u)).exists(v => v != k && pending.exists(_._1 == v)))
          var ready = pending.filterNot(e => waits(e._1, e._2))
          while (ready.nonEmpty || pending.nonEmpty) {
            val now = if (ready.nonEmpty) ready else pending
            val known = tSubstitution(solved)
            for ((k, p) <- now) {
              val upper = ta.meet(p.pu.map(known).filterNot(TU.hasInferenceVars))
              if (upper.isInstanceOf[BottomType]) return None
              solved = solved + (k -> upper)
            }
            pending = pending.filterNot(e => now.exists(_._1 == e._1))
            ready = pending.filterNot(e => waits(e._1, e._2))
          }
          val sub = (if (toBounds) TU.topIvars else TU.killIvars) compose tSubstitution(solved)
	  val newMap = cMap(nc, sub)
//	  println("newMap: " + newMap)
          if(isTrue(newMap))
            Some((sub compose tUnifier, oUnifier, nUnifier))
          else newMap match {
            // A size that only the type variables' bounds name, as a where-clause
            // variable in the bound of a function's type parameter, is fixed once
            // the type variables are: solve what their solutions leave, sizes alone.
            case And(rts, ros, rns) if rts.isEmpty && ros.isEmpty && !rns.isEmpty =>
              slv(newMap, toBounds).map { case (t2, o2, n2) =>
                (t2 compose sub compose tUnifier, o2 compose oUnifier, n2 compose nUnifier) }
